create table accounting_receivable_settlements (id bigint generated by default as identity primary key, tenant_id bigint not null references tenants(id), company_id bigint not null references companies(id), branch_id bigint not null references branches(id), customer_id bigint not null references customers(id), invoice_id bigint, amount numeric(18,2) not null, currency varchar(3) not null, settled_at timestamptz not null, idempotency_key varchar(160) not null, posting_reference varchar(160) not null, unique(tenant_id,idempotency_key));
